css:
.gosim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2733;
    background:
        linear-gradient(180deg, rgba(255,255,255,0.0) 0%, rgba(255,255,255,0.0) 100%),
        repeating-linear-gradient(135deg, #eef1f5 0px, #eef1f5 22px, #e9edf2 22px, #e9edf2 44px);
    border-radius: 16px;
}

.gosim-container * {
    box-sizing: border-box;
}

.gosim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f2238 0%, #1b3a5b 55%, #225e6b 100%);
    color: #f1f6fb;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #14304c;
    box-shadow: 0 14px 34px rgba(15, 34, 56, 0.30);
}

.gosim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    text-transform: uppercase;
}

.gosim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #ffb454;
    background: rgba(255, 180, 84, 0.14);
    border: 1px solid rgba(255, 180, 84, 0.36);
    padding: 5px 14px;
    border-radius: 4px;
}

.gosim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfdcea;
}

.gosim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #54647a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.gosim-period-counter #currentDay,
.gosim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b3a5b;
}

.gosim-round-name {
    background: #1b3a5b;
    color: #ffffff;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.4px;
    margin-left: 4px;
    text-transform: uppercase;
}

.gosim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a00;
    background: rgba(255, 180, 84, 0.18);
    border: 1px solid rgba(255, 180, 84, 0.55);
    padding: 4px 12px;
    border-radius: 4px;
}

.gosim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.gosim-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #d7dee7;
    box-shadow: 0 4px 14px rgba(31, 39, 51, 0.07);
    border-left: 5px solid #1b3a5b;
}

.gosim-card-savings { border-left-color: #1f8a5b; }
.gosim-card-control { border-left-color: #225e6b; }
.gosim-card-market { border-left-color: #2f6fb0; }
.gosim-card-resilience { border-left-color: #c77d1a; }

.gosim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #6b7a8d;
}

.gosim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #15233a;
    font-variant-numeric: tabular-nums;
}

.gosim-card-savings .gosim-value { color: #1f8a5b; }
.gosim-card-control .gosim-value { color: #225e6b; }
.gosim-card-market .gosim-value { color: #2f6fb0; }
.gosim-card-resilience .gosim-value { color: #c77d1a; }

.gosim-sublabel {
    font-size: 0.76rem;
    color: #7c8a9b;
    line-height: 1.35;
}

.gosim-savings-hit .gosim-value { color: #1f8a5b; }
.gosim-savings-short .gosim-value { color: #c0392b; }

.gosim-control-high { border-left-color: #1f8a5b; }
.gosim-control-high .gosim-value { color: #1f8a5b; }
.gosim-control-low { border-left-color: #c0392b; }
.gosim-control-low .gosim-value { color: #c0392b; }

.gosim-resilience-high { border-left-color: #1f8a5b; }
.gosim-resilience-high .gosim-value { color: #1f8a5b; }
.gosim-resilience-low { border-left-color: #c0392b; }
.gosim-resilience-low .gosim-value { color: #c0392b; }

.gosim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #15233a;
    border: 1px solid #14304c;
    color: #e6eef7;
    padding: 12px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.gosim-budget-bar #gapDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #4fd39a;
}

.gosim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c77d1a;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 39, 51, 0.07);
}

.gosim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.gosim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #15233a;
    margin-bottom: 6px;
}

.gosim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4658;
}

.gosim-briefing-text strong { color: #1b3a5b; }
.gosim-briefing-text em { color: #9a5a00; font-style: italic; }

.gosim-controls {
    background: #ffffff;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d7dee7;
    box-shadow: 0 4px 14px rgba(31, 39, 51, 0.07);
}

.gosim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #15233a;
    border-bottom: 2px solid #e3e9f0;
    padding-bottom: 8px;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.gosim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3647;
    margin: 16px 0 6px;
}

.gosim-container select,
.gosim-container input[type="number"] {
    width: 100%;
    padding: 11px 12px;
    border: 1px solid #c3ccd8;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1f2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.gosim-container select:focus,
.gosim-container input[type="number"]:focus {
    outline: none;
    border-color: #225e6b;
    box-shadow: 0 0 0 3px rgba(34, 94, 107, 0.16);
}

.gosim-container select option {
    background-color: #ffffff;
    color: #1f2733;
}

.gosim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c77d1a;
}

.gosim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #54647a;
    margin-top: 4px;
}

.gosim-range-readout span:last-child {
    color: #9a5a00;
    font-weight: 800;
}

.gosim-hint {
    font-size: 0.8rem;
    color: #7c8a9b;
    margin-top: 4px;
    line-height: 1.4;
}

.gosim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.gosim-container .btn-primary {
    background: linear-gradient(135deg, #16314e 0%, #225e6b 100%);
    border: none;
    color: #ffffff;
    padding: 12px 28px;
    border-radius: 7px;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    box-shadow: 0 8px 18px rgba(22, 49, 78, 0.30);
}

.gosim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.gosim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c3ccd8;
    color: #54647a;
    background: transparent;
}

.gosim-coach {
    background: linear-gradient(160deg, #15233a 0%, #1b3a44 100%);
    color: #dbe6f1;
    border: 1px solid #14304c;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 34, 56, 0.25);
}

.gosim-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffb454;
    margin-bottom: 8px;
}

.gosim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.gosim-coach-body strong { color: #4fd39a; }
.gosim-coach-body em { color: #ffb454; font-style: italic; }

.gosim-history,
.gosim-chart {
    background: #ffffff;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d7dee7;
    box-shadow: 0 4px 14px rgba(31, 39, 51, 0.07);
}

.gosim-history h3,
.gosim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #15233a;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.gosim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2a3647;
}

.gosim-container table#usfHistoryTable th {
    background: #15233a;
    color: #ffb454;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #14304c;
}

.gosim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e3e9f0;
    color: #3a4658;
}

.gosim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f5f8fb;
}

.gosim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .gosim-container {
        padding: 14px;
    }
    .gosim-header h1 {
        font-size: 1.7rem;
    }
    .gosim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .gosim-value {
        font-size: 2.05rem;
    }
    .gosim-clock {
        margin-left: 0;
    }
    .gosim-period-counter {
        font-size: 0.88rem;
    }
    .gosim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .gosim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === gosim-cm: completion debrief (appended, adapter 1.1.0) === */
.gosim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.gosim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.gosim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.gosim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.gosim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.gosim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.gosim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.gosim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.gosim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.gosim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.gosim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.gosim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.gosim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.gosim-cm-insights { margin: 0; padding-left: 20px; }
.gosim-cm-insights li { margin: 5px 0; line-height: 1.4; }

