(function() {
    'use strict';

    class GoingGlobalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Going Global`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Maasvliet Mobility Systems B.V.).
            this.SAVINGS_TARGET = 45;        // EUR 45M annual cost recovery required to restore margin
            this.CONTEXT_BASE = 70;          // EUR ~70M relocatable context cost base (deepest offshore saving)
            this.US_PIPELINE = 83;           // ~EUR 83M US order pipeline (USD 90M)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    savings: 0,              // EUR M annual recurring cost recovered
                    control: 70,             // retained control over core IP (0-100)
                    market: 30,              // US pipeline served + incentive fit (0-100)
                    resilience: 50,          // tariff / export-control robustness (0-100)
                    ipLeaked: false,         // core activity sent offshore / outsourced
                    concentrated: false,     // single flagged-jurisdiction lane
                    savingsHistory: [0],
                    controlHistory: [70],
                    marketHistory: [30],
                    resilienceHistory: [50],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately wrong-leaning mix that fires several
                // of the documented Common Errors — a blind click-through must NOT auto-win.
                state.decisions = {
                    classify: `unsure`,
                    candidate: `all`,
                    lesson: `vendor`,
                    location: `offshore`,
                    governance: `outsourced`,
                    ipPlacement: `offshore`,
                    depth: 40,
                    dualSource: `single`,
                    entryMode: `export`,
                    bridge: `wait`,
                    content: `freight`,
                    capital: 15,
                    shockResponse: `absorb`,
                    reconcile: `savings`,
                    pitch: `cheaper`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cl = document.getElementById(`classifyInput`);
                const ca = document.getElementById(`candidateInput`);
                const le = document.getElementById(`lessonInput`);
                if (cl) decisions.classify = cl.value;
                if (ca) decisions.candidate = ca.value;
                if (le) decisions.lesson = le.value;
                if (!decisions.classify || !decisions.candidate || !decisions.lesson) {
                    warn(`warn_r1_incomplete`); return false;
                }
            } else if (round === 2) {
                const lo = document.getElementById(`locationInput`);
                const go = document.getElementById(`governanceInput`);
                const ip = document.getElementById(`ipPlacementInput`);
                const de = document.getElementById(`depthInput`);
                const du = document.getElementById(`dualSourceInput`);
                if (lo) decisions.location = lo.value;
                if (go) decisions.governance = go.value;
                if (ip) decisions.ipPlacement = ip.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (du) decisions.dualSource = du.value;
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 3) {
                const em = document.getElementById(`entryModeInput`);
                const br = document.getElementById(`bridgeInput`);
                const co = document.getElementById(`contentInput`);
                const cp = document.getElementById(`capitalInput`);
                if (em) decisions.entryMode = em.value;
                if (br) decisions.bridge = br.value;
                if (co) decisions.content = co.value;
                if (cp) decisions.capital = parseFloat(cp.value);
                if (!Number.isFinite(decisions.capital) || decisions.capital < 0 || decisions.capital > 120) {
                    warn(`warn_capital_range`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockResponseInput`);
                const re = document.getElementById(`reconcileInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shockResponse = sh.value;
                if (re) decisions.reconcile = re.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let savingsDelta = 0, controlDelta = 0, marketDelta = 0, resilienceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Round 1 — Diagnose. Match location to criticality; name the 2019 lesson.
                // Common Error 1: offshoring the crown jewels begins here if the IP is mis-classified.
                switch (d.classify) {
                    case `core`: controlDelta += 10; resilienceDelta += 4; coachKey = `coach_r1_core`; break;
                    case `context`: controlDelta -= 10; coachKey = `coach_r1_context`; break;
                    case `unsure`: controlDelta -= 6; resilienceDelta -= 3; coachKey = `coach_r1_unsure`; break;
                }

                switch (d.candidate) {
                    case `context`: controlDelta += 6; resilienceDelta += 3; break;
                    case `all`: controlDelta -= 8; coachKey = `coach_r1_candall`; break;  // crown jewels in the candidate set
                    case `none`: savingsDelta -= 0; controlDelta += 2; marketDelta -= 2; coachKey = `coach_r1_candnone`; break;
                }

                switch (d.lesson) {
                    case `criticality`: controlDelta += 6; resilienceDelta += 4; if (d.classify === `core` && d.candidate === `context`) coachKey = `coach_r1_sharp`; break;
                    case `vendor`: controlDelta -= 4; coachKey = `coach_r1_vendor`; break;
                    case `bad luck`: controlDelta -= 6; resilienceDelta -= 3; coachKey = `coach_r1_luck`; break;
                }

                summaryKey = (d.classify === `core` && d.candidate === `context` && d.lesson === `criticality`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Round 2 — Sourcing footprint. The savings-dominant round.
                // Location sets the per-point saving rate on the relocated context base.
                const frac = d.depth / 100;
                let rate = 0;            // EUR M of saving per 100% of context base relocated
                switch (d.location) {
                    case `offshore`: rate = this.CONTEXT_BASE * 0.78; resilienceDelta -= 6; break;   // deepest saving, most exposed
                    case `nearshore`: rate = this.CONTEXT_BASE * 0.62; resilienceDelta += 8; marketDelta += 4; break; // tariff-light, Mexico serves US
                    case `onshore`: rate = this.CONTEXT_BASE * 0.10; controlDelta += 4; break;        // recovers almost nothing
                }
                let gross = rate * frac;

                // Governance (independent axis — Van Gorp). Captive keeps control; outsourcing maximises saving.
                switch (d.governance) {
                    case `captive`: gross *= 0.92; controlDelta += 8; resilienceDelta += 3; break;
                    case `outsourced`: gross *= 1.05; controlDelta -= 10; break;
                    case `mixed`: gross *= 0.98; controlDelta += 4; resilienceDelta += 2; break;
                }
                savingsDelta += gross;

                // Common Error 1: the IP placement is what actually triggers the 2019 repeat.
                switch (d.ipPlacement) {
                    case `onshore`: controlDelta += 12; resilienceDelta += 4; break;
                    case `nearshore`: controlDelta += 2; savingsDelta += 3; resilienceDelta -= 2; break;
                    case `offshore`:
                        controlDelta -= 24; savingsDelta += 12; ds.ipLeaked = true;
                        coachKey = `coach_r2_ipleak`;
                        break;
                }
                if (d.ipPlacement === `offshore` && d.governance === `outsourced`) {
                    // The exact 2019 configuration: core IP, offshore, third party.
                    controlDelta -= 10;
                    coachKey = `coach_r2_repeat2019`;
                }

                // Common Error 5 / Decision-tree 5: concentration risk.
                if (d.dualSource === `dual`) {
                    savingsDelta -= 4; resilienceDelta += 14;
                    if (coachKey === `coach_default`) coachKey = `coach_r2_dual`;
                } else {
                    if (d.location === `offshore`) { resilienceDelta -= 12; ds.concentrated = true; if (coachKey === `coach_default`) coachKey = `coach_r2_single`; }
                    else { resilienceDelta -= 4; }
                }

                // Deep, fast offshoring stacks ramp + tariff exposure.
                if (d.location === `offshore` && d.depth >= 70) { resilienceDelta -= 6; marketDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r2_deepfast`; }

                if (coachKey === `coach_default`) coachKey = `coach_r2_balanced`;

                const hitTarget = (ds.savings + savingsDelta) >= this.SAVINGS_TARGET;
                summaryKey = (hitTarget && !ds.ipLeaked && d.dualSource === `dual`) ? `sum_r2_good` :
                             (ds.ipLeaked ? `sum_r2_ipleak` :
                             (ds.concentrated ? `sum_r2_concentrated` : `sum_r2_weak`));
            } else if (round === 3) {
                // Round 3 — North American entry mode. Trades cost/speed vs control/incentive fit.
                switch (d.entryMode) {
                    case `export`:
                        marketDelta += 6; resilienceDelta -= 8;        // fast now, but tariff/content exposed
                        coachKey = `coach_r3_export`;
                        break;
                    case `license`:
                        marketDelta += 8; controlDelta -= 16;          // capital-light, leaks IP
                        coachKey = `coach_r3_license`;
                        break;
                    case `jv`:
                        marketDelta += 16; controlDelta -= 4; resilienceDelta += 4;  // shares cost/risk, incentive-eligible, dilutes control
                        coachKey = `coach_r3_jv`;
                        break;
                    case `greenfield`:
                        marketDelta += 22; controlDelta += 8;          // max control + content fit, but slow
                        coachKey = `coach_r3_greenfield`;
                        break;
                }

                // Common Error 3: control reflex — greenfield WITHOUT a bridge strands the live pipeline.
                if (d.entryMode === `greenfield`) {
                    if (d.bridge === `bridge`) { marketDelta += 10; coachKey = `coach_r3_bridged`; }
                    else { marketDelta -= 18; coachKey = `coach_r3_reflex`; }   // 30 months while the pipeline is live now
                } else if (d.entryMode === `jv` && d.bridge === `bridge`) {
                    marketDelta += 4;
                } else if ((d.entryMode === `export` || d.entryMode === `license`) && d.bridge === `none`) {
                    marketDelta += 2;   // already serves the pipeline this quarter
                }

                // Common Error 4: policy-blind export. Modelling the domestic-content rule is decisive.
                switch (d.content) {
                    case `modelled`: marketDelta += 10; resilienceDelta += 8; break;
                    case `freight`: marketDelta -= 4; resilienceDelta -= 4; if (d.entryMode === `export`) coachKey = `coach_r3_policyblind`; break;
                    case `ignored`: marketDelta -= 12; resilienceDelta -= 8; coachKey = `coach_r3_ignorepolicy`; break;
                }
                // Export that ignores content fails the incentive test outright.
                if (d.entryMode === `export` && d.content !== `modelled`) { marketDelta -= 8; }

                // Capital commitment: enough buys control + eligibility; over-committing to a slow plant strands it.
                const cap = d.capital;
                if (d.entryMode === `greenfield`) {
                    if (cap >= 60) { controlDelta += 4; if (d.bridge !== `bridge`) marketDelta -= 4; }
                    else { marketDelta -= 4; }   // under-capitalised plant
                } else {
                    if (cap >= 90) { marketDelta -= 6; coachKey = `coach_r3_stranded`; }  // over-committing to a light mode
                    else if (cap >= 25) { marketDelta += 4; controlDelta += 2; }
                }

                summaryKey = ((d.entryMode === `jv` || (d.entryMode === `greenfield` && d.bridge === `bridge`)) && d.content === `modelled`) ? `sum_r3_good` :
                             ((d.entryMode === `greenfield` && d.bridge !== `bridge`) ? `sum_r3_reflex` :
                             ((d.entryMode === `export` && d.content !== `modelled`) ? `sum_r3_policyblind` : `sum_r3_weak`));
            } else if (round === 4) {
                // Round 4 — Integrate, stress-test, pitch the board that remembers 2019.
                switch (d.shockResponse) {
                    case `contingency`:
                        if (ds.concentrated || ds.ipLeaked) {
                            // Claiming a contingency you never built in R2.
                            resilienceDelta -= 6; controlDelta -= 2; coachKey = `coach_r4_nocontingency`;
                        } else {
                            resilienceDelta += 16; marketDelta += 4; coachKey = `coach_r4_contingency`;
                        }
                        break;
                    case `absorb`:
                        savingsDelta -= 6; resilienceDelta -= 8; marketDelta -= 4; coachKey = `coach_r4_absorb`;  // eat the +6-10% landed cost
                        break;
                    case `rebuild`:
                        resilienceDelta -= 4; marketDelta -= 6; coachKey = `coach_r4_rebuild`;  // no contingency, re-plan live
                        break;
                }

                switch (d.reconcile) {
                    case `integrated`: controlDelta += 6; marketDelta += 6; resilienceDelta += 6; break;
                    case `savings`: resilienceDelta -= 4; controlDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_savingsled` : coachKey; break;
                    case `control`: marketDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_controlled` : coachKey; break;
                }

                // The board explicitly references 2019. The dimensional rebuttal only lands if the plan earned it.
                switch (d.pitch) {
                    case `dimensions`:
                        if (!ds.ipLeaked && !ds.concentrated) { controlDelta += 12; resilienceDelta += 6; coachKey = `coach_r4_rebuttal`; }
                        else { controlDelta -= 6; coachKey = `coach_r4_hollow`; }   // claims it differs from 2019 while repeating it
                        break;
                    case `cheaper`: controlDelta -= 8; resilienceDelta -= 4; coachKey = `coach_r4_cheaper`; break;
                    case `trust`: controlDelta -= 10; coachKey = `coach_r4_trust`; break;
                }

                if (d.conviction >= 60) { resilienceDelta += 4; controlDelta += 3; }
                else if (d.conviction <= 25) { resilienceDelta -= 4; controlDelta -= 3; }

                summaryKey = (d.shockResponse === `contingency` && !ds.ipLeaked && !ds.concentrated && d.reconcile === `integrated` && d.pitch === `dimensions`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas. Savings is cumulative EUR M; the 0-100 KPIs are clamped.
            ds.savings = Math.round((ds.savings + savingsDelta) * 10) / 10;
            ds.control = Math.max(0, Math.min(100, Math.round(ds.control + controlDelta)));
            ds.market = Math.max(0, Math.min(100, Math.round(ds.market + marketDelta)));
            ds.resilience = Math.max(0, Math.min(100, Math.round(ds.resilience + resilienceDelta)));

            ds.savingsHistory.push(ds.savings);
            ds.controlHistory.push(ds.control);
            ds.marketHistory.push(ds.market);
            ds.resilienceHistory.push(ds.resilience);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                savings: ds.savings,
                savingsDelta: Math.round(savingsDelta * 10) / 10,
                control: ds.control,
                controlDelta: Math.round(controlDelta),
                market: ds.market,
                marketDelta: Math.round(marketDelta),
                resilience: ds.resilience,
                resilienceDelta: Math.round(resilienceDelta),
                ipLeaked: ds.ipLeaked,
                concentrated: ds.concentrated,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Netherlands / EUR. Spanish notation: "45,0 M€" (comma decimal, € after).
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
        }

