        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.controlHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                goChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.controlHistory },
                        { data: ds.marketHistory },
                        { data: ds.resilienceHistory }
                    ]
                }
            };
        }

        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const savings = ds.savings;
            const control = Math.round(ds.control);
            const market = Math.round(ds.market);
            const resilience = Math.round(ds.resilience);
            const savingsScore = Math.max(0, Math.min(100, (savings / this.SAVINGS_TARGET) * 100));
            return Math.round(savingsScore * 0.28 + control * 0.30 + market * 0.20 + resilience * 0.22);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const savings = ds.savings;
            const control = Math.round(ds.control);
            const market = Math.round(ds.market);
            const resilience = Math.round(ds.resilience);

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const hitTarget = savings >= this.SAVINGS_TARGET;
            const ipSafe = control >= 60 && !ds.ipLeaked;
            const resilient = resilience >= 55 && !ds.concentrated;
            const served = market >= 55;

            let performanceKey = `grade_short`;
            if (hitTarget && ipSafe && resilient && served && composite >= 75) performanceKey = `grade_board`;
            else if (ds.ipLeaked) performanceKey = `grade_ipleak`;
            else if (hitTarget && ipSafe && resilient) performanceKey = `grade_costclosed`;
            else if (ds.concentrated && hitTarget) performanceKey = `grade_concentrated`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && ipSafe && resilient && served) insights.push(window.mySimulation.t(`insight_strong`));
            else if (ds.ipLeaked) insights.push(window.mySimulation.t(`insight_ipleak`));
            else if (ds.concentrated) insights.push(window.mySimulation.t(`insight_concentrated`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!hitTarget) insights.push(window.mySimulation.t(`insight_savings_short`));
            else insights.push(window.mySimulation.t(`insight_savings_hit`));
            if (market < 45) insights.push(window.mySimulation.t(`insight_market_weak`));
            if (control >= 65 && resilience >= 60 && !ds.ipLeaked) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                savings: savings,
                control: control,
                market: market,
                resilience: resilience,
                hitTarget: hitTarget,
                ipSafe: ipSafe,
                resilient: resilient,
                served: served,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (hitTarget && ipSafe && resilient && served),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_short`);
            const badge = (ok, okKey, noKey) => `<span class="gosim-cm-badge ${ok ? `gosim-cm-ok` : `gosim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="gosim-cm-kpi"><div class="gosim-cm-kpi-v">${esc(val)}</div><div class="gosim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.hitTarget === true, `cm_badge_target`, `cm_badge_shortfall`)
                       + badge(s.ipSafe === true, `cm_badge_ipsafe`, `cm_badge_ipleak`)
                       + badge(s.resilient === true, `cm_badge_resilient`, `cm_badge_concentrated`)
                       + badge(s.served === true, `cm_badge_served`, `cm_badge_marketweak`);
            const savings = (s.savings != null) ? this._fmtMoney(Number(s.savings)) : `\u2014`;
            return `<div class="gosim-cm">`
                + `<div class="gosim-cm-head"><div class="gosim-cm-score">${score}<span class="gosim-cm-max">/100</span></div>`
                + `<div class="gosim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="gosim-cm-badges">${badges}</div>`
                + `<div class="gosim-cm-kpis">`
                + kpi(t(`cm_kpi_savings`), savings)
                + kpi(t(`cm_kpi_control`), (s.control != null ? s.control : `\u2014`))
                + kpi(t(`cm_kpi_market`), (s.market != null ? s.market : `\u2014`))
                + kpi(t(`cm_kpi_resilience`), (s.resilience != null ? s.resilience : `\u2014`))
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="gosim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.ipLeaked) return window.mySimulation.t(`hint_ipleak`);
            if (ds.concentrated) return window.mySimulation.t(`hint_concentrated`);
            if (state.currentPeriod >= 2 && ds.savings < this.SAVINGS_TARGET) return window.mySimulation.t(`hint_savings`);
            if (state.currentPeriod >= 3 && ds.market < 40) return window.mySimulation.t(`hint_market`);
            if (ds.control >= 65 && ds.resilience >= 60 && ds.savings >= this.SAVINGS_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

